from collections import defaultdict
sol=[]
for w in range(6):
    for p in range(50):
        c=p//25; n=p%25; x=n%5; y=n//5
        if w<5:
            g=(y - w*x)%5 + 5*c
        else:
            g=x + 5*c
        sol.append(g)
print(len(sol))
print(sol)
# verify
ok=True
for w in range(6):
    counts=[0]*10
    for p in range(50): counts[sol[w*50+p]]+=1
    if counts != [5]*10:
        print('bad counts',w,counts); ok=False
pairweeks=defaultdict(list)
for w in range(6):
    groups=defaultdict(list)
    for p in range(50): groups[sol[w*50+p]].append(p)
    for g,players in groups.items():
        for i in range(len(players)):
            for j in range(i+1,len(players)):
                pairweeks[tuple(sorted((players[i],players[j])))].append(w)
repeats=[(pair,ws) for pair,ws in pairweeks.items() if len(ws)>1]
print('ok',ok,'repeats',len(repeats),'pairs met',len(pairweeks))
